import java.util.*;
import org.simplepoint.platform.composition.ModuleCatalog;
import org.simplepoint.platform.composition.ModuleDictionaryPlan;
import org.simplepoint.platform.dictionary.DictionaryContribution;
import org.simplepoint.plugin.rbac.tenant.service.initialize.DictionaryDeclarationWriter;
import org.springframework.transaction.annotation.Transactional;

public class VerifyDictionaryTransactionArtifacts {
  public static void main(String[] args) throws Exception {
    var loader = VerifyDictionaryTransactionArtifacts.class.getClassLoader();
    var catalog = ModuleCatalog.discover(loader);
    var declarations = ModuleDictionaryPlan.declarations(catalog.plan(List.of("oidc", "notification")));
    if (declarations.size() != 2) throw new AssertionError("Missing dictionary declarations");
    var method = DictionaryDeclarationWriter.class.getMethod("apply", DictionaryContribution.class);
    if (method.getAnnotation(Transactional.class) == null) throw new AssertionError("Writer missing transaction");
    for (String name : List.of("DictionaryServiceImpl", "DictionaryItemServiceImpl")) {
      var type = Class.forName("org.simplepoint.plugin.rbac.tenant.service.impl." + name);
      for (var write : type.getDeclaredMethods()) {
        if (!write.isBridge() && Set.of("create", "modifyById", "removeById", "removeByIds", "removeAll").contains(write.getName())
            && write.getAnnotation(Transactional.class) == null)
          throw new AssertionError("Untransactional dictionary mutation: " + write);
      }
    }
    for (String name : List.of("ExternalIdentityProviderDictionaryInitializer", "NotificationDictionaryInitializer")) {
      var type = Class.forName("org.simplepoint.common.server.initialize." + name);
      var beans = Arrays.stream(type.getDeclaredMethods()).filter(m -> m.isAnnotationPresent(org.springframework.context.annotation.Bean.class)).toList();
      if (beans.size() != 1 || !Arrays.equals(beans.getFirst().getParameterTypes(), new Class<?>[]{DictionaryDeclarationWriter.class}))
        throw new AssertionError("Legacy adapter does not use aggregate writer");
    }
    var migration = "META-INF/simplepoint/modules/identity/db/postgresql/V6__dictionary_catalog_revision.sql";
    var urls = Collections.list(loader.getResources(migration));
    if (urls.size() != 1) throw new AssertionError("Missing/duplicate dictionary migration");
    try (var stream = loader.getResourceAsStream("META-INF/simplepoint/modules/identity/db/manifest.properties")) {
      var manifest = new Properties(); manifest.load(stream);
      if (!manifest.getProperty("migrations").contains("V6__dictionary_catalog_revision.sql")
          || !manifest.getProperty("tables").contains("simpoint_dictionary_catalog_revision"))
        throw new AssertionError("Migration not declared");
    }
    var boundary = Collections.list(loader.getResources("org/simplepoint/data/jpa/transaction/CatalogWriteBoundary.class"));
    if (boundary.size() != 1 || !boundary.getFirst().toString().contains("simplepoint-data-jpa.jar"))
      throw new AssertionError("Shared catalog boundary is not packaged once");
    Class.forName("org.simplepoint.plugin.rbac.tenant.rest.controller.DictionaryExceptionHandler");
    System.out.println("Installed distribution: shared catalog boundary, transactional dictionary writers, aggregate legacy adapters, unique declared V6 migration and HTTP error adapter verified.");
  }
}
